//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.procJob;
scwin.gAcptNo;
scwin.gIsuCd;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF41001.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/*익일영업일 가져옴*/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.date.select";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/*시장조치 내용 불러오기*/
scwin.fn_getMktReq = function() {
    var res = window.confirm("시장조치내역을 불러오시겠습니까?");
    if (res) {
        scwin.procJob = "시장조치요청";
        trs_Save.Action = $c.lc.fn_encodeNSession("/MktVerifSystem.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=sendMktReqManagement");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_getDate)";
        trs_Save.Parameters = "CALND_DD=" + $c.stf.getObjectValue(edt_SDate);
        trs_Save.Post();
    }
};
scwin.fn_read_sync_cnt = function(pBzNm, pQryIdCnt) {
    dts_Cnt.DataID = encodeURI(scwin.fn_QryUrl_Cnt(pBzNm, pQryIdCnt));
    dts_Cnt.reset();
    return dts_Cnt.getTotalRow();
};
scwin.fn_QryUrl_Cnt = function(pBzNm, pQryIdCnt) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_CNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + pQryIdCnt + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate);
    return url;
};
scwin.fn_gridAddRow = function(pQryIdCnt, pQryId, pBzNm, gCnt) {
    dts_List_1.insertRow();
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "QRY_ID_CNT", pQryIdCnt);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "QRY_ID", pQryId);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "BZ_NM", pBzNm);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT_LDS", dts_Cnt.getCellData(1, "CNT_LDS"));
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT_MKT", dts_Cnt.getCellData(1, "CNT_MKT"));
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT_BIGYO", dts_Cnt.getCellData(1, "CNT_BIGYO"));
};
scwin.fn_QryUrl_Info = function(row, pBzNm, pQryId) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_INFO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + pQryId + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate);
    if (row == 1 || row == 2 || row == 3 || row == 6 || row == 7 || row == 8 || row == 9 || row == 10 || row == 12 || row == 14 || row == 15) {
        // jackal_22.09.23 세그먼트 추가 행사가액 정정 추가 jackal_17.10.19
        url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_INFO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + pQryId + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate);
    } else if (row == 4 || row == 13) {
        url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_INFO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + pQryId + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param06=" + $c.stf.getObjectValue(edt_SDate);
    } else if (row == 5) {
        // 거래정지
        url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_INFO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + pQryId + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param06=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param08=" + $c.stf.getObjectValue(edt_SDate);
    } else if (row == 11) {
        // 단일판매 공급계약 공시 중
        url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_INFO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + pQryId;
    }
    return url;
};
scwin.fn_read_sync_info = function(row, colid) {
    dts_List_2.DataID = encodeURI(scwin.fn_QryUrl_Info(row, dts_List_1.getCellData(row, 'BZ_NM'), dts_List_1.getCellData(row, 'QRY_ID')));
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};


//시장조치검증시스템 재무정보  list
scwin.fn_list = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dts_List_1.removeAll();
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=MKTVERIFSYS_COMP_CNT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.comp.all.cnt" +
            // 101 추가/변경
            "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate) +
            // 099 폐지
            "&{P}param05=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param06=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param08=" + $c.stf.getObjectValue(edt_SDate) +
            // 308 정리매매
            "&{P}param09=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param10=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param11=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param12=" + $c.stf.getObjectValue(edt_SDate) +
            // 203 관리종목
            "&{P}param13=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param14=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param15=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param16=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param17=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param18=" + $c.stf.getObjectValue(edt_SDate) +
            // 201 거래정지
            "&{P}param19=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param20=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param21=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param22=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param23=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param24=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param25=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param26=" + $c.stf.getObjectValue(edt_SDate) +
            // 301 불성실공시
            "&{P}param27=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param28=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param29=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param30=" + $c.stf.getObjectValue(edt_SDate) +
            // 401 상호변경
            "&{P}param31=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param32=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param33=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param34=" + $c.stf.getObjectValue(edt_SDate) +
            // 407 결산기변경
            "&{P}param35=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param36=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param37=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param38=" + $c.stf.getObjectValue(edt_SDate) +
            // 205 우회상장지정
            "&{P}param39=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param40=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param41=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param42=" + $c.stf.getObjectValue(edt_SDate) +
            // 402 업종변경
            "&{P}param43=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param44=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param45=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param46=" + $c.stf.getObjectValue(edt_SDate) +
            //311 소속부변경
            "&{P}param47=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param48=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param49=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param50=" + $c.stf.getObjectValue(edt_SDate) +
            // 312 투자주의환기종목지정 						 
            "&{P}param51=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param52=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param53=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param54=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param55=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param56=" + $c.stf.getObjectValue(edt_SDate) +
            //404 행사가액 정정 jackal_17.10.19
            "&{P}param57=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param58=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param59=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param60=" + $c.stf.getObjectValue(edt_SDate) +
            //319 세그먼트 변경 jackal_22.09.23
            "&{P}param61=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param62=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param63=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param64=" + $c.stf.getObjectValue(edt_SDate);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();
        $c.cm.ShowWin(grd_List_1);
        dts_List_2.removeAll();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=MKTVERIFSYS_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param06=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate);
        dts_ListBond.DataID = encodeURI(url);
        dts_ListBond.reset();
        $c.cm.ShowWin(grd_ListBond);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=PRTDEPO_CONFRM_DOC_SUBMIT_LIST_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.select.prtdepoconfrm.submit_status.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate);
        dts_BackList.DataID = encodeURI(url);
        dts_BackList.reset();
        $c.cm.ShowWin(dts_BackList);
    }
};



/*시장정보수신된 내용이 있는지 체크*/
scwin.fn_btncnt = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_CNT_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.rdsrcvmktact.cnt.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate);
    dts_btnCnt.DataID = encodeURI(url);
    dts_btnCnt.reset();
};


/*버튼 사용여부*/
scwin.fn_btnSet = function() {
    scwin.fn_btncnt();
    // 여러번 수신받을수 있도록 수정  jackal 10.05.27 
    /*
		if(dts_btnCnt.NameString(1,"BTNCNT") > 0){
			btn_MktReq.src = "../img/btn/btn_mktlist_d.gif";
