		*/

};



//공시뷰터로 인한 함수
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_ListBond.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsuCd = dts_ListBond.getCellData(eval(obj), "ISU_CD");
};
