scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_2, "시장조치 데이타비교 [" + $c.stf.getObjectValue(edt_SDate) + " ] ", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_ListBond, "시장조치 감사보고서 추출 데이타비교 [" + $c.stf.getObjectValue(edt_SDate) + " ] ", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_BackList, "의무보유확약서 제출현황 데이타비교 [" + $c.stf.getObjectValue(edt_SDate) + " ] ", "", "8");
    }
};
