    scwin.fn_btnSet();
    if (dts_btnCnt.getCellData(1, "BTNCNT") > 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    } else {
        $c.win.alert("시장조치 수신 내역이 없습니다.");
    }
    scwin.fn_list();
};
