scwin.btn_MktReq_onclick = function() {
    // 시간 체크 추가 jackal_20.05.24
    // 배치 기동시간 이후에 작동토록 수정
    var vCurDate = $c.ut.cGetToday("yyyymmddhhmmss");
    var vBatchTime = $c.ut.cGetToday("yyyymmdd") + '173000';
    if (vCurDate < vBatchTime) {
        $c.win.alert('시장조치내역 불러오기 기능은 17시 30분 이후에 가능합니다.');
        return;
    }
    scwin.fn_getMktReq();
};
