    await $c.frame.CreateDialogFrame("ULDSTF41002.gfm", "/lstmgt/ULDSTF41002.gfm", "화면표시기준", 100, 10, 735, 785, "window");
};
scwin.grd_BackList_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId2(row);
    if (colid == "DOC_TITLE") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.grd_ListBond_OnDblClick = async function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "DISCLS_PROCS_DDTM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "ADM_YN") {
        await $c.frame.CreateDialogFrame("ULDSTF41003.gfm", "/lstmgt/ULDSTF41003.gfm?IsuCd=" + scwin.gIsuCd + "&CalndDd=" + $c.stf.getObjectValue(edt_SDate) + "&TypeCd=1", "시장조치시스템 수신 내역", 100, 10, 640, 350, "window");
    } else if (colid == "HALT_YN") {
        await $c.frame.CreateDialogFrame("ULDSTF41003.gfm", "/lstmgt/ULDSTF41003.gfm?IsuCd=" + scwin.gIsuCd + "&CalndDd=" + $c.stf.getObjectValue(edt_SDate) + "&TypeCd=2", "시장조치시스템 수신 내역", 100, 10, 640, 350, "window");
    }
};
scwin.grd_List_1_OnClick = function(row, colid) {
    scwin.fn_read_sync_info(row, colid);
    scwin.fn_gridList2_Col_Init();
    if (row == 1) {
        scwin.fn_gridList2_Col_101();
    } else if (row == 2) {
        scwin.fn_gridList2_Col_099();
    } else if (row == 3) {
        scwin.fn_gridList2_Col_308();
    } else if (row == 4) {
        scwin.fn_gridList2_Col_203();
    } else if (row == 5) {
        scwin.fn_gridList2_Col_201();
    } else if (row == 6) {
        scwin.fn_gridList2_Col_301();
    } else if (row == 7) {
        scwin.fn_gridList2_Col_401();
    } else if (row == 8) {
        scwin.fn_gridList2_Col_407();
    } else if (row == 9) {
        scwin.fn_gridList2_Col_205();
    } else if (row == 10) {
        scwin.fn_gridList2_Col_402();
    } else if (row == 11) {
        scwin.fn_gridList2_Col_374();
    } else if (row == 12) {
        //	소속부변경
        scwin.fn_gridList2_Col_311();
    } else if (row == 13) {
        //	투자주의환기
        scwin.fn_gridList2_Col_312();
    } else if (row == 14) {
        scwin.fn_gridList2_Col_404();
    } else if (row == 15) {
        //	jackal_22.09.23 세그먼트 추가
        scwin.fn_gridList2_Col_319();
    }
};
