scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex(1);

    // 여러번 수신받을수 있도록 수정  jackal 10.05.27 
    btn_MktReq.src = "../img/btn/btn_mktlist.gif";
    btn_MktReq.setDisabled(false);
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(1, "CALND_DD"));
    scwin.fn_list();
    scwin.fn_btnSet(); // 초기 화면에 반영되로록 수정

};
